var answers=[],pos=0,view=document.getElementById('view');
function button(text,fn,cls){var b=document.createElement('button');b.textContent=text;b.className=cls||'';b.addEventListener('click',fn);view.appendChild(b);}
function scrollPage(){window.scrollTo(0,0);}
function home(){view.innerHTML='<div class="meta">6 道题 / 约 1 分钟</div><h1>你的周末<br>适合怎样回血？</h1><p>安静独处、出门漫游、熟人小聚，还是完成一件小事？给下个周末找一点灵感。</p>';button('开始测一测 →',function(){answers=[];pos=0;question();},'primary');}
function question(){view.innerHTML='<div class="meta">'+(pos+1)+' / 6 · 按最近的感受选</div><div class="bar"><div style="width:'+((pos+1)/6*100)+'%"></div></div><h2>'+questions[pos][0]+'</h2>';questions[pos][1].forEach(function(t,i){button(String.fromCharCode(65+i)+'  '+t,function(){answers[pos]=i;pos++;if(pos===6){report();}else{question();}scrollPage();});});if(pos>0){button('← 返回上一题',function(){pos--;question();scrollPage();},'back');}}
function tally(a){var counts=[0,0,0,0];a.forEach(function(x){counts[x]++;});var max=Math.max.apply(null,counts);return {counts:counts,winners:counts.map(function(c,i){return c===max?i:-1;}).filter(function(i){return i>=0;})};}
function report(){var t=tally(answers);view.innerHTML='<div class="meta">你的周末灵感卡</div><h1>'+(t.winners.length>1?'混合补给型':results[t.winners[0]][0])+'</h1><p>'+(t.winners.length>1?'这几种选择在你的答案里并列。可以各挑一小段，拼成自己的周末。':'这次的选择里，你更偏向这种休息安排。')+'</p>';t.winners.forEach(function(i){var r=results[i];var card=document.createElement('section');card.className='card';var h=document.createElement('h2');h.textContent=r[0];card.appendChild(h);[r[1],r[2],r[3]].forEach(function(s){var p=document.createElement('p');p.textContent=s;card.appendChild(p);});view.appendChild(card);});var d=document.createElement('details');var summary=document.createElement('summary');summary.textContent='结果是怎么算的？';d.appendChild(summary);var p=document.createElement('p');p.textContent='六题每个选择计一次。四类选择次数分别为：'+t.counts.join(' / ')+'（静音、漫游、熟人、小事）。次数最多的一类作为结果，并列则全部展示。这是当下偏好整理，不代表固定人格。';d.appendChild(p);view.appendChild(d);button('修改最后一题',function(){pos=5;question();scrollPage();},'back');button('重新测一次',function(){home();scrollPage();},'primary');}
home();